// Any PMS/HTTP error lands here. Store codes only (no free text, no PHI) and hand off to workflow 12.
const input = $('Sub-workflow trigger').first().json;
const args = input.args || {};
const err = $json.error || {};
const http_status = (err && (err.httpCode || err.status || err.statusCode)) || null;
return [{ json: {
  call_id: input.call_id,
  patient_id: args.patient_id || null,
  location: input.location,
  reason: 'pms_error',
  requested: { fn: 'reschedule_appointment', slot_id: args.slot_id || null, appointment_id: args.appointment_id || null, http_status: http_status ? String(http_status) : null },
} }];

// Returns a cached NexHealth bearer token when still valid (cached 50 min in workflow static data).
// Static data only persists for production (activated) executions; manual test runs re-authenticate.
const sd = $getWorkflowStaticData('global');
const valid = sd.nexhealthToken && sd.nexhealthTokenExpires && Number(sd.nexhealthTokenExpires) > Date.now();
return [{ json: { token: valid ? sd.nexhealthToken : null } }];

// POST https://nexhealth.info/authenticates responds { code, data: { token } }.
const sd = $getWorkflowStaticData('global');
const token = $json.data && $json.data.token;
if (!token) { throw new Error('NexHealth /authenticates returned no token'); }
sd.nexhealthToken = token;
sd.nexhealthTokenExpires = Date.now() + 50 * 60 * 1000;
return [{ json: { token } }];

// ---- shared helpers (duplicated in each workflow on purpose: n8n Code nodes cannot import) ----
const crypto = require('crypto');
const TZ = $env.PRACTICE_TZ || 'America/New_York';
const SALT = $env.PATIENT_HASH_SALT || '';
const envJson = (k) => { try { return JSON.parse($env[k] || '{}'); } catch (e) { return {}; } };
const sha256 = (s) => crypto.createHash('sha256').update(String(s)).digest('hex');
const patientRef = (id) => (id === null || id === undefined || id === '') ? null : sha256(String(id) + SALT);
const fmt = (d, opts) => new Intl.DateTimeFormat('en-US', Object.assign({ timeZone: TZ }, opts)).format(d);
const ordinal = (n) => n + ((n % 10 === 1 && n !== 11) ? 'st' : (n % 10 === 2 && n !== 12) ? 'nd' : (n % 10 === 3 && n !== 13) ? 'rd' : 'th');
const sayWhen = (iso) => { const d = new Date(iso); return fmt(d, { weekday: 'long' }) + ' the ' + ordinal(Number(fmt(d, { day: 'numeric' }))) + ' at ' + fmt(d, { hour: 'numeric', minute: '2-digit' }); };
const providerFirst = (id, fallbackName) => {
  const names = envJson('NEXHEALTH_PROVIDER_NAMES');
  if (id !== null && id !== undefined && names[String(id)]) return names[String(id)];
  if (fallbackName) { const parts = String(fallbackName).replace(/^(dr\.?|doctor)\s+/i, '').trim().split(/\s+/); return parts.length ? 'Dr. ' + parts[parts.length - 1] : null; }
  return null;
};
const e164 = (p) => { if (!p) return null; let d = String(p).replace(/[^\d+]/g, ''); if (d.startsWith('+')) return d; d = d.replace(/\D/g, ''); if (d.length === 10) return '+1' + d; if (d.length === 11 && d.startsWith('1')) return '+' + d; return d ? '+' + d : null; };
// ---- end helpers ----

// Input args: { appointment_id?, patient_id?, slot_id }. If appointment_id is absent the next upcoming appointment of patient_id is used.
const input = $('Sub-workflow trigger').first().json;
const args = input.args || {};
const parts = String(args.slot_id || '').split('|');
const start_time = parts[0] || null;
if (!start_time || isNaN(new Date(start_time))) throw new Error('reschedule_appointment requires a slot_id returned by get_slots');
const appt = { start_time };
if (parts[2]) appt.operatory_id = Number(parts[2]);
// NexHealth PATCH cannot change provider_id; a slot with a different provider keeps the original provider.
const body = { appt };
const sub = $env.NEXHEALTH_SUBDOMAIN || '';
let lookup_url = null;
if (!args.appointment_id) {
  if (!args.patient_id) throw new Error('reschedule_appointment requires appointment_id or patient_id');
  const lq = new URLSearchParams({ subdomain: sub, location_id: String(input.location_id || ''), start: new Date().toISOString(), end: new Date(Date.now() + 120 * 24 * 3600 * 1000).toISOString(), cancelled: 'false', per_page: '25' });
  lq.append('patient_ids[]', String(args.patient_id));
  lookup_url = 'https://nexhealth.info/appointments?' + lq.toString();
}
return [{ json: { token: $json.token, appointment_id: args.appointment_id ? String(args.appointment_id) : null, lookup_url, patch_query: new URLSearchParams({ subdomain: sub }).toString(), body, location: input.location } }];

const data = Array.isArray($json.data) ? $json.data : [];
const upcoming = data.filter(a => !a.cancelled && !a.unavailable && new Date(a.start_time) > new Date()).sort((a, b) => new Date(a.start_time) - new Date(b.start_time));
if (!upcoming.length) return [{ json: { appointment_id: null } }];
return [{ json: { appointment_id: String(upcoming[0].id), start_time: upcoming[0].start_time } }];

const req = $('Build request').first().json;
const appointment_id = $json.appointment_id || req.appointment_id;
return [{ json: { token: req.token, url: 'https://nexhealth.info/appointments/' + encodeURIComponent(appointment_id) + '?' + req.patch_query, body: req.body, appointment_id: String(appointment_id), location: req.location } }];

// ---- shared helpers (duplicated in each workflow on purpose: n8n Code nodes cannot import) ----
const crypto = require('crypto');
const TZ = $env.PRACTICE_TZ || 'America/New_York';
const SALT = $env.PATIENT_HASH_SALT || '';
const envJson = (k) => { try { return JSON.parse($env[k] || '{}'); } catch (e) { return {}; } };
